#[component]
pub fn Icon(
    #[prop(into)] name: String,
    #[prop(default = 18)] size: u32,
    #[prop(optional, into)] class: String,
) -> impl IntoView {
    let inner = paths(&name);
    view! {
        <svg
            class=format!("icon {class}")
            width=size
            height=size
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linecap="round"
            stroke-linejoin="round"
            aria-hidden="true"
            inner_html=inner
        ></svg>
    }
}
